СПО_СКОРОСТИ = ('IV', 'III', 'II', 'I')

def табл(таблица: dict[int, float], глубина_м: float) -> float:
    кл = sorted(таблица)
    if not кл[0] <= глубина_м <= кл[-1]:
        raise ValueError(f'глубина {глубина_м:.1f} м вне оцифрованного диапазона {кл[0]}-{кл[-1]} м: нормативного значения для неё НЕТ')
    for a, b in zip(кл, кл[1:]):
        if a <= глубина_м <= b:
            д = (глубина_м - a) / (b - a)
            return таблица[a] + д * (таблица[b] - таблица[a])
    raise AssertionError('диапазон проверен выше, сюда попасть нельзя')

def k_колонна(диаметр_мм: float | None) -> float:
    if диаметр_мм is None:
        return 1.0
    return K_КОЛОННА_168 if диаметр_мм >= 168.0 else 1.0

def спо_цикл_мин(труб: int, диаметр_нкт_мм: float=73.0, агрегат: str='А-50У', автомат: bool=True) -> float:
    спуск = труб * СПО_МИН_НА_ТРУБУ[автомат, диаметр_нкт_мм, 'Спуск']
    предел = max((СПО_ДОПУСК_ТРУБ[агрегат, диаметр_нкт_мм, с] for с in СПО_СКОРОСТИ if (агрегат, диаметр_нкт_мм, с) in СПО_ДОПУСК_ТРУБ))
    if труб > предел:
        raise ValueError(f'{труб} труб превышает допускаемое число {предел} шт для агрегата {агрегат} при НКТ {диаметр_нкт_мм} мм (§209): подъём такой колонны этим агрегатом нормой не предусмотрен')
    подъём = 0.0
    осталось = труб
    for с in СПО_СКОРОСТИ:
        кл = (агрегат, диаметр_нкт_мм, с)
        if кл not in СПО_ДОПУСК_ТРУБ:
            continue
        доп = СПО_ДОПУСК_ТРУБ[кл]
        на_этой = min(осталось, доп)
        подъём += на_этой * СПО_МИН_НА_ТРУБУ[автомат, диаметр_нкт_мм, с]
        осталось -= на_этой
        if осталось <= 0:
            break
    assert осталось == 0, f'расписание подъёма не покрыло {осталось} труб'
    return спуск + подъём
